"""Helpers shared by the course labs: loading the collection, exact search and recall."""
import numpy as np


def unit(x):
    """Scale every row to length 1, so that inner product equals cosine similarity."""
    return (x / np.linalg.norm(x, axis=1, keepdims=True)).astype(np.float32)


def load(folder="data", normalise=True):
    base, queries = np.load(f"{folder}/base.npy"), np.load(f"{folder}/queries.npy")
    return (unit(base), unit(queries)) if normalise else (base, queries)


def top_k(scores, k):
    """Column indices of the k highest scores in each row, best first, without sorting whole rows."""
    k = min(k, scores.shape[1])
    part = np.argpartition(-scores, k - 1, axis=1)[:, :k]
    order = np.argsort(-np.take_along_axis(scores, part, axis=1), axis=1, kind="stable")
    return np.take_along_axis(part, order, axis=1)


def exact_search(queries, base, k=10, metric="ip", batch=256):
    """Brute-force k-NN, a batch of queries at a time. metric 'ip': inner product (cosine on unit vectors);
    'l2': Euclidean distance, using ||q - x||^2 = ||q||^2 - 2 q.x + ||x||^2."""
    base_sq = (base.astype(np.float64) ** 2).sum(axis=1).astype(np.float32) if metric == "l2" else None
    out = []
    for s in range(0, len(queries), batch):
        sims = queries[s:s + batch] @ base.T              # one matrix multiplication per batch
        if metric == "l2":
            sims = 2 * sims - base_sq                     # ||q||^2 is the same for every x: drop it
        out.append(top_k(sims, k))
    return np.vstack(out)


def recall_at_k(found, truth, k=10):
    """Share of the true k nearest neighbours that a search returned, averaged over the queries."""
    return float(np.mean([len(set(f[:k]) & set(t[:k])) / k for f, t in zip(found, truth)]))

