-- Create the extension and the tables, and load the vectors.
CREATE EXTENSION IF NOT EXISTS vector;
SELECT extversion AS pgvector_version FROM pg_extension WHERE extname = 'vector';
DROP TABLE IF EXISTS items, queries, exact;
CREATE TABLE items (
    id        bigint PRIMARY KEY,
    tenant    smallint NOT NULL,
    embedding vector(64) NOT NULL
);
CREATE TABLE queries (id int PRIMARY KEY, embedding vector(64) NOT NULL);
\copy items FROM '/lab/data/pg_items.csv' WITH (FORMAT csv, HEADER true)
\copy queries FROM '/lab/data/pg_queries.csv' WITH (FORMAT csv, HEADER true)
ANALYZE items;
SELECT count(*) AS items, pg_size_pretty(pg_total_relation_size('items')) AS table_size FROM items;

-- Exact top 10 for every query: no vector index yet, so PostgreSQL scans and sorts all 50,000 rows.
\timing on
EXPLAIN (COSTS OFF)
SELECT id FROM items ORDER BY embedding <=> (SELECT embedding FROM queries WHERE id = 0) LIMIT 10;
CREATE TABLE exact AS
SELECT q.id AS qid, x.id
FROM queries q
CROSS JOIN LATERAL (SELECT id FROM items ORDER BY embedding <=> q.embedding LIMIT 10) x;
SELECT count(*) AS exact_rows FROM exact;

-- Build an HNSW index for cosine distance, then measure recall@10 against the exact answers.
\timing on
SET maintenance_work_mem = '256MB';
CREATE INDEX items_hnsw ON items USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);
\timing off
SELECT pg_size_pretty(pg_relation_size('items_hnsw')) AS index_size;
EXPLAIN (COSTS OFF)
SELECT id FROM items ORDER BY embedding <=> (SELECT embedding FROM queries WHERE id = 0) LIMIT 10;

CREATE OR REPLACE FUNCTION recall_at_10(ef int) RETURNS numeric LANGUAGE plpgsql AS $$
DECLARE r numeric;
BEGIN
    PERFORM set_config('hnsw.ef_search', ef::text, true);      -- for this transaction only
    SELECT round(avg(hits) / 10.0, 3) INTO r FROM (
        SELECT q.id, (SELECT count(*) FROM exact e WHERE e.qid = q.id AND e.id IN
                        (SELECT id FROM items ORDER BY embedding <=> q.embedding LIMIT 10)) AS hits
        FROM queries q) t;
    RETURN r;
END $$;
SELECT ef AS ef_search, recall_at_10(ef) FROM unnest(ARRAY[10, 20, 40, 100]) AS ef;

-- Filtered search: the 10 nearest items for tenant 7, which owns about 0.5% of the rows.
SET hnsw.ef_search = 40;
SELECT round(avg(n), 1) AS avg_rows_returned FROM queries q
CROSS JOIN LATERAL (SELECT count(*) AS n FROM (
    SELECT id FROM items WHERE tenant = 7 ORDER BY embedding <=> q.embedding LIMIT 10) r) c;

-- pgvector 0.8.0 and later: keep scanning the index until enough rows pass the filter.
SET hnsw.iterative_scan = relaxed_order;
SELECT round(avg(n), 1) AS avg_rows_returned_iterative FROM queries q
CROSS JOIN LATERAL (SELECT count(*) AS n FROM (
    SELECT id FROM items WHERE tenant = 7 ORDER BY embedding <=> q.embedding LIMIT 10) r) c;
RESET hnsw.iterative_scan;

-- With a B-tree index on tenant, the planner can pre-filter instead: fetch tenant 7's rows, then sort them exactly.
CREATE INDEX items_tenant ON items (tenant);
ANALYZE items;
EXPLAIN (COSTS OFF)
SELECT id FROM items WHERE tenant = 7
ORDER BY embedding <=> (SELECT embedding FROM queries WHERE id = 0) LIMIT 10;
SELECT round(avg(n), 1) AS avg_rows_returned_prefilter FROM queries q
CROSS JOIN LATERAL (SELECT count(*) AS n FROM (
    SELECT id FROM items WHERE tenant = 7 ORDER BY embedding <=> q.embedding LIMIT 10) r) c;
